@dsl_user_op
def _triangular_coordinate(self, index, *, loc=None, ip=None):
    root = cutlass.Float32(cute.math.sqrt(cutlass.Float32(index * 8 + 1)))
    row = ((root - 1.0) * 0.5).to(cutlass.Int32)
    base = row * (row + 1) // 2
    row = row - (base > index).to(cutlass.Int32)
    base = row * (row + 1) // 2
    row = row + (base + row + 1 <= index).to(cutlass.Int32)
    base = row * (row + 1) // 2
    return row, index - base, cutlass.Int32(0)


@dsl_user_op
def _g2048_triangular_coordinate(self, index, *, loc=None, ip=None):
    batch, triangle_index = divmod(
        index, self.params.cluster_shape_major_fdd
    )
    batch = cutlass.Int32(batch)
    triangle_index = cutlass.Int32(triangle_index)
    root = cutlass.Float32(
        cute.math.sqrt(cutlass.Float32(triangle_index * 8 + 1))
    )
    row = ((root - 1.0) * 0.5).to(cutlass.Int32)
    base = row * (row + 1) // 2
    row = row - (base > triangle_index).to(cutlass.Int32)
    base = row * (row + 1) // 2
    row = row + (base + row + 1 <= triangle_index).to(cutlass.Int32)
    base = row * (row + 1) // 2
    return row, triangle_index - base, batch


class _TriangularGemm(_AlphaBetaGemm):
    @staticmethod
    def _compute_grid(output, tile, cluster, max_clusters):
        rows = cute.ceil_div(output.shape[0], tile[0] * 2)
        total = rows * (rows + 1) // 2
        params = cutlass_utils.PersistentTileSchedulerParams(
            (total * 2, 1, 1), (2, 1, 1)
        )
        grid = cutlass_utils.StaticPersistentTileScheduler.get_grid_shape(
            params, max_clusters
        )
        return params, grid


class _G2048TriangularGemm(_AlphaBetaGemm):
    @staticmethod
    def _compute_grid(output, tile, cluster, max_clusters):
        rows = cute.ceil_div(output.shape[0], tile[0] * cluster[0])
        total = rows * (rows + 1) // 2
        params = cutlass_utils.PersistentTileSchedulerParams(
            (total * cluster[0], cluster[1], output.shape[2]),
            (*cluster, 1),
        )
        grid = cutlass_utils.StaticPersistentTileScheduler.get_grid_shape(
            params, max_clusters
        )
        return params, grid


